   */
  def put_concrete_inputs(engage_ap : FAA_Autopilot_Engagement.Engage_AP_Command.Type,
                          command_status : FAA_Autopilot_Engagement.Engage_Command_Status.Type,
                          guidance_valid : FAA_Autopilot_Engagement.Guidance_Readiness.Type,
                          attitude_acceptable : FAA_Autopilot_Engagement.Attitude_Acceptability.Type,
                          ap_availability : FAA_Autopilot_Engagement.AP_Availability.Type): Unit = {
    put_engage_ap(engage_ap)
    put_command_status(command_status)
    put_guidance_valid(guidance_valid)
    put_attitude_acceptable(attitude_acceptable)
    put_ap_availability(ap_availability)
  }


  /** helper function to check Engagement_Decision_Thread_control_process_engagement_decision's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param ap_guidance_request method that will be called with the value of the outgoing data
   *        port 'ap_guidance_request'.
   * @param ap_status method that will be called with the value of the outgoing data
   *        port 'ap_status'.
   * @param ap_on method that will be called with the value of the outgoing data
   *        port 'ap_on'.
   */
  def check_concrete_output(ap_guidance_request: FAA_Autopilot_Engagement.AP_Guidance_Request.Type => B,
                            ap_status: FAA_Autopilot_Engagement.AP_Status.Type => B,
                            ap_on: FAA_Autopilot_Engagement.AP_On_Indication.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val ap_guidance_requestValue: FAA_Autopilot_Engagement.AP_Guidance_Request.Type = get_ap_guidance_request().get
    if(!ap_guidance_request(ap_guidance_requestValue)) {
      testFailures = testFailures :+ st"'ap_guidance_request' did not match expected: value of the outgoing data port is ${ap_guidance_requestValue}"
    }
    val ap_statusValue: FAA_Autopilot_Engagement.AP_Status.Type = get_ap_status().get
    if(!ap_status(ap_statusValue)) {
      testFailures = testFailures :+ st"'ap_status' did not match expected: value of the outgoing data port is ${ap_statusValue}"
    }
    val ap_onValue: FAA_Autopilot_Engagement.AP_On_Indication.Type = get_ap_on().get
    if(!ap_on(ap_onValue)) {
      testFailures = testFailures :+ st"'ap_on' did not match expected: value of the outgoing data port is ${ap_onValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


